package ru.neverland.runtime;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import org.bukkit.*;
import org.bukkit.event.inventory.*;
import com.palmergames.bukkit.towny.*;
import com.palmergames.bukkit.towny.object.*;
import ru.neverland.core.*;
import ru.neverland.townycouncil.*;
import static ru.neverland.townycouncil.Delegations.*;

/** Reuses only the explicit offline actor/owning-region harness, not the admission scenarios. */
public final class DelegationsProbe extends AdmissionsProbe {
    NeverLandTownyCouncil councilPlugin;CouncilService council;DelegationService service;DelegationRepository repository;DelegationMenus menus;Grant grant,revoked,expired;
    @Override void setup()throws Exception{
        councilPlugin=(NeverLandTownyCouncil)Bukkit.getPluginManager().getPlugin("NeverLandTownyCouncil");council=councilPlugin.council();service=council.delegations();repository=service.repository();menus=(DelegationMenus)field(councilPlugin,"delegationMenus");mayor=actor(M,"DelegationMayor");applicant=actor(P,"DelegationResident");sponsor=actor(S,"DelegationMinister");
        check(councilPlugin.isEnabled()&&councilPlugin.getDescription().getVersion().equals("0.2.0")&&council.healthy(),"actual Council 0.2 delegation service and legacy council services enabled");
        if(restart){resumeDelegations();return;}
        var u=TownyUniverse.getInstance();u.newTownInternal("DelegationsCity",T);town=TownyAPI.getInstance().getTown(T);for(var e:Map.of(P,"DelegationResident",M,"DelegationMayor",S,"DelegationMinister").entrySet()){var r=u.getDataSource().newResident(e.getValue(),e.getKey());r.setTown(town);r.save();}town.setMayor(TownyAPI.getInstance().getResident(M));var claim=new TownBlock(0,0,u.getWorld(world.getName()));u.addTownBlock(claim);claim.setTown(town);town.setHomeBlock(claim);claim.save();town.setSpawn(origin);town.save();
        council.appoint(mayor,town,MinisterRole.DEFENSE,S);check(council.holders(T).get("defense").equals(S)&&council.decision(T,P,"export").equals("DEFAULT"),"existing permanent ministry retained while resident starts without delegated export");
        denied(()->service.proposal(applicant,town,S,TownAction.EXPORT,1,"self"),"wildcard/admin-style permissions never substitute for actual mayor");denied(()->service.proposal(mayor,town,M,TownAction.EXPORT,1,"self"),"mayor cannot create self-delegation");
        menus.command(mayor,new String[]{"delegate","DelegationResident","export","1","Помочь отчёту"});check(windows.get(M).getItem(29).getType()==Material.LIME_DYE&&lore(mayor,13).contains("МСК"),"actual delegation command opens exact expiry and separate confirmation");var quote=((Map<?,?>)field(menus,"quotes")).get(M);confirmation=(UUID)field(quote,"id");
        var atomic=Class.forName("ru.neverland.core.AtomicFiles",true,councilPlugin.getClass().getClassLoader());var f=atomic.getDeclaredField("writers");f.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)f.get(null);var lock=locks.computeIfAbsent(councilPlugin.getDataFolder().toPath().resolve("delegations.yml").toAbsolutePath().normalize(),p->new ReentrantLock());release=new CountDownLatch(1);var ready=new CountDownLatch(1);var worker=new Thread(()->{lock.lock();ready.countDown();try{release.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{lock.unlock();}},"native-delayed-delegation-file");worker.setDaemon(true);worker.start();if(!ready.await(1,TimeUnit.SECONDS))throw new AssertionError("lock fixture not ready");
        var click=new InventoryClickEvent(view(mayor,M),InventoryType.SlotType.CONTAINER,29,ClickType.LEFT,InventoryAction.PICKUP_ALL);menus.click(click);check(click.isCancelled(),"confirmation click cannot move menu items");later(3,()->{check(repository.busy()&&council.decision(T,P,"export").equals("DEFAULT"),"real blocked writer cannot grant unconfirmed authority");check(SuiteState.tryRun("live region while delegation disk blocked",()->{}),"owning region remains responsive while actual delegation file waits");release.countDown();pollDelegations(60);});
    }
    void pollDelegations(int remaining)throws Exception{if(repository.busy()){if(remaining<=0)throw new AssertionError("delayed grant failed to complete");later(1,()->pollDelegations(remaining-1));return;}grant=repository.state().grants().get(T+"/"+P+"/export");check(grant!=null&&council.decision(T,P,"export").equals("ALLOW")&&CouncilAccess.check(applicant,T,"export",false),"acknowledged grant authorizes real shared city action bridge");denied(()->menus.command(mayor,new String[]{"delegate-confirm",confirmation.toString()}),"same confirmation cannot issue a second or extended grant");
        var rules=council.rules(town);council.changeAccess(mayor,town,rules.mayor(),rules.revision(),"",P,"export","deny");check(council.decision(T,P,"export").equals("DENY")&&!service.active(T,P,TownAction.EXPORT),"mayor permanent deny overrides temporary grant immediately");rules=council.rules(town);council.changeAccess(mayor,town,rules.mayor(),rules.revision(),"",P,"export","default");check(council.decision(T,P,"export").equals("ALLOW")&&council.temporaryRights(T,P).get("export").equals(grant.expiresAt()),"removing explicit deny reveals still-live grant and exact primitive expiry API");
        var governance=(org.bukkit.plugin.java.JavaPlugin)Bukkit.getPluginManager().getPlugin("NeverLandTownyGovernance");var govMenus=(ru.neverland.governance.gui.GovernanceMenuManager)field(governance.getCommand("governance").getExecutor(),"menus");govMenus.openCouncil(mayor);check(windows.get(M).getItem(47).getType()==Material.CLOCK,"actual unified governance council menu exposes temporary rights without navigation collision");
        councilPlugin.getConfig().set("delegations.accept-new",false);denied(()->service.proposal(mayor,town,P,TownAction.BUILD,1,"disabled"),"feature switch blocks new grants");check(council.decision(T,P,"export").equals("ALLOW")&&repository.state().grants().get(grant.key()).equals(grant),"feature switch preserves confirmed rights and fixed expiration");councilPlugin.getConfig().set("delegations.accept-new",true);
        var next=service.proposal(mayor,town,P,TownAction.STORAGE_WITHDRAW,1,"Временная разгрузка");await(service.grant(mayor,next,repository.state().revision()),saved->{try{check(council.decision(T,P,"storage_withdraw").equals("ALLOW"),"second granular action can be granted independently");await(service.revoke(mayor,next,"Разгрузка завершена"),later->{try{revoked=repository.state().grants().get(next.key());check(revoked.revoked()&&council.decision(T,P,"storage_withdraw").equals("DEFAULT")&&CouncilAccess.check(applicant,T,"storage_withdraw",true),"confirmed revoke removes temporary contribution while preserving independent legacy rights");seedExpired();}catch(Exception e){fail(e);}});}catch(Exception e){fail(e);}});
    }
    void seedExpired()throws Exception{long now=System.currentTimeMillis();expired=new Grant(UUID.randomUUID(),T,P,M,"build",now-3*HOUR,now-HOUR,"DelegationMayor","Explicit already-expired native fixture",false,1);var before=repository.state();var all=new HashMap<>(before.grants());all.put(expired.key(),expired);await(repository.commit(before,new State(all,before.history(),before.revision()+1)),saved->{try{check(council.decision(T,P,"build").equals("DEFAULT"),"explicit old expired fixture cannot authorize building");menus.open(mayor,town,0);check(windows.get(M).getSize()==54&&windows.get(M).getItem(49).getType()==Material.WRITABLE_BOOK,"native board exposes temporary grants and distinct create action");Files.writeString(proof.resolve("expected-delegations.txt"),grant.expiresAt()+"\n"+grant.grantedAt()+"\n"+revoked.expiresAt()+"\n"+expired.expiresAt()+"\n");var control=ModulePauseStore.file(councilPlugin.getDataFolder().toPath().getParent());ModulePauseStore.save(control,new ModulePauseStore.State(Set.of(),Map.of(councilPlugin.getName(),new ModulePauseStore.Entry(false,System.currentTimeMillis()-120_000))));finishDelegations();}catch(Exception e){fail(e);}});}
    void resumeDelegations()throws Exception{town=TownyAPI.getInstance().getTown(T);var expected=Files.readAllLines(proof.resolve("expected-delegations.txt"));check(council.holders(T).get("defense").equals(S),"original permanent ministry survives real native restart");grant=repository.state().grants().get(T+"/"+P+"/export");revoked=repository.state().grants().get(T+"/"+P+"/storage_withdraw");expired=repository.state().grants().get(T+"/"+P+"/build");check(grant.expiresAt()>=Long.parseLong(expected.get(0))+120_000&&grant.grantedAt()==Long.parseLong(expected.get(1)),"real module pause extends still-live authority but preserves historical grant date");check(council.decision(T,P,"export").equals("ALLOW")&&CouncilAccess.check(applicant,T,"export",false),"native restart restores temporary authority through existing public bridge");check(revoked.revoked()&&revoked.expiresAt()==Long.parseLong(expected.get(2))&&council.decision(T,P,"storage_withdraw").equals("DEFAULT"),"revoked authority remains revoked and its historical deadline never shifts");check(expired.expiresAt()==Long.parseLong(expected.get(3))&&council.decision(T,P,"build").equals("DEFAULT"),"pause cannot resurrect authority that expired before pause began");check(repository.state().history().size()==3,"two real grants and one revoke retain exactly three durable history entries");var audit=councilPlugin.getDataFolder().toPath().resolve("audit");boolean found=false;for(var file:Files.list(audit).toList())if(file.getFileName().toString().endsWith(".tsv")&&Files.readString(file).contains("COUNCIL_DELEGATION"))found=true;check(found,"administrative TSV journal retains exact delegation operations after restart");finishDelegations();}
    void finishDelegations()throws Exception{TownyUniverse.getInstance().getDataSource().saveAll();Files.writeString(proof.resolve((restart?"restart":"first")+"-passed.txt"),"PASS "+checks+" assertions; genuine Folia/Towny/Council command, native menus, shared action bridge, real delayed file and pause/restart, legacy ministry preserved; explicit offline Player/InventoryView/EntityScheduler and expired-grant fixture; no GUI client, money cap or bank operation claimed\n");Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
}
